@import url('');
:root{color-scheme:dark;--ink:#f3f5ff;--muted:#929bb9;--cyan:#5ef4ef;--violet:#a883ff;--orange:#ff9a58;--panel:rgba(13,17,39,.84);font-family:'Trebuchet MS',Arial,sans-serif}*{box-sizing:border-box}html,body{height:100%;margin:0;background:#080b1b;color:var(--ink);overflow:hidden}body{display:grid;place-items:center}.game-shell{position:relative;width:min(100vw,1600px);height:min(100dvh,900px);min-height:320px;overflow:hidden;background:#0a1026;isolation:isolate;box-shadow:0 20px 100px #0009}#game{position:absolute;inset:0;width:100%;height:100%;display:block}.vignette{position:absolute;inset:0;pointer-events:none;background:linear-gradient(180deg,rgba(5,8,21,.48),transparent 25%,transparent 68%,rgba(5,8,21,.48)),radial-gradient(ellipse at center,transparent 35%,rgba(3,5,16,.47) 100%);z-index:1}.topbar{position:absolute;z-index:4;left:0;right:0;top:0;height:72px;padding:0 34px;display:flex;align-items:center;justify-content:space-between;border-bottom:1px solid rgba(160,194,255,.1);background:linear-gradient(180deg,rgba(4,8,23,.64),transparent)}.brand{display:flex;align-items:center;gap:11px;text-decoration:none;color:var(--ink)}.brand-mark{width:32px;height:32px;display:grid;place-items:center;border:1px solid var(--cyan);color:var(--cyan);font-size:20px;font-weight:700;transform:rotate(45deg);line-height:1}.brand-mark span{position:absolute;font-size:8px;transform:rotate(-45deg) translate(8px,-9px);color:#fff}.brand-name{font-size:12px;letter-spacing:2.2px;font-weight:700}.brand-name span{color:var(--cyan)}.mission{font:500 10px 'Courier New',monospace;letter-spacing:1.6px;color:#c3cae0;display:flex;align-items:center;gap:9px}.mission i{font-style:normal;color:var(--cyan)}.live-dot,.eyebrow span{width:6px;height:6px;border-radius:50%;background:var(--cyan);box-shadow:0 0 12px var(--cyan);display:inline-block}.icon-button{width:40px;height:40px;color:var(--ink);border:1px solid rgba(179,197,245,.25);background:#12193280;border-radius:50%;font-size:17px;cursor:pointer;transition:.2s}.icon-button:hover{border-color:var(--cyan);color:var(--cyan)}.hud{position:absolute;z-index:3;top:92px;left:34px;display:flex;gap:10px;align-items:stretch}.hud-card{min-width:132px;padding:11px 14px 10px;background:rgba(8,13,34,.76);border:1px solid rgba(141,168,230,.16);backdrop-filter:blur(8px);clip-path:polygon(0 0,calc(100% - 10px) 0,100% 10px,100% 100%,0 100%)}.crystal-card{min-width:160px}.hud-label{font:500 9px 'Courier New',monospace;letter-spacing:1.5px;color:#aab4d3;display:flex;justify-content:space-between;align-items:center;white-space:nowrap}.tiny-gem{color:var(--cyan);font-size:10px;margin-right:5px;text-shadow:0 0 10px var(--cyan)}.crystal-count{display:flex;align-items:baseline;gap:5px;margin:2px 0 7px}.crystal-count strong{font-size:25px;line-height:1;font-weight:600;letter-spacing:-1px}.crystal-count>span{font:11px 'Courier New',monospace;color:#8994b6}.meter{height:3px;background:#29304b;overflow:hidden}.meter span{display:block;width:0;height:100%;background:var(--cyan);box-shadow:0 0 9px var(--cyan);transition:width .25s}.health-card{min-width:125px}.hearts{margin-top:5px;display:flex;gap:5px;font-size:20px;line-height:1;color:#ff6b85;text-shadow:0 0 10px #ff4567}.hearts span.empty{color:#38405b;text-shadow:none}.progress-card{min-width:150px}.progress-line{display:flex;gap:8px;align-items:center;margin-top:12px}.progress-line>span{font:11px 'Courier New',monospace;color:#fff;min-width:30px}.progress-line .meter{width:72px}.toast{position:absolute;z-index:5;top:22%;left:50%;transform:translate(-50%,-10px);opacity:0;pointer-events:none;padding:10px 15px;border:1px solid #5ef4ef55;background:#0b1530e8;color:var(--cyan);font:500 10px 'Courier New',monospace;letter-spacing:1.5px;transition:opacity .25s,transform .25s}.toast.show{opacity:1;transform:translate(-50%,0)}.screen{position:absolute;z-index:6;inset:0;display:flex;align-items:center;justify-content:center;background:rgba(4,7,21,.51);backdrop-filter:blur(4px);transition:opacity .3s}.screen.hidden{opacity:0;pointer-events:none;visibility:hidden}.screen.visible{opacity:1;visibility:visible}.screen-panel{position:relative;z-index:2;width:min(460px,48%);padding:40px 42px;background:linear-gradient(140deg,rgba(12,18,44,.96),rgba(7,11,29,.94));border:1px solid rgba(126,175,226,.24);box-shadow:0 22px 80px #02040e99;clip-path:polygon(0 0,calc(100% - 20px) 0,100% 20px,100% 100%,0 100%)}.intro-panel{margin-right:24%;}.eyebrow{display:flex;align-items:center;gap:10px;color:#aeb9d5;font:500 9px 'Courier New',monospace;letter-spacing:2px}.screen h1,.screen h2{margin:18px 0 13px;font-size:clamp(38px,5.2vw,65px);font-weight:700;line-height:.91;letter-spacing:-3px}.screen h1 em,.screen h2 em{font-style:normal;color:var(--cyan);text-shadow:0 0 28px #5ef4ef35}.intro-copy,.compact-panel p{max-width:340px;color:#aab4ce;font-size:13px;line-height:1.7}.intro-copy b{color:#f4f6ff;font-weight:600}.mission-stats{display:flex;align-items:center;gap:15px;margin:23px 0 20px}.mission-stats div{display:grid;gap:4px}.mission-stats strong{font:500 18px 'Courier New',monospace;color:#fff}.mission-stats span{font:8px 'Courier New',monospace;color:#929dbb;letter-spacing:1px;white-space:nowrap}.mission-stats i{height:28px;width:1px;background:#ffffff20}.primary-button{display:flex;align-items:center;justify-content:space-between;width:100%;height:48px;padding:0 16px;border:0;background:var(--cyan);color:#07141e;font-weight:700;letter-spacing:1.5px;font-size:11px;cursor:pointer;transition:transform .18s,filter .18s;clip-path:polygon(0 0,calc(100% - 12px) 0,100% 12px,100% 100%,0 100%)}.primary-button:hover{filter:brightness(1.13);transform:translateY(-2px)}.primary-button b{font-size:18px}.key-hint{margin-top:16px;color:#8792b2;font:9px 'Courier New',monospace;letter-spacing:.7px;white-space:nowrap}.key-hint kbd{padding:3px 5px;color:#d9e2ff;border:1px solid #56607b;border-radius:3px;margin:0 2px}.key-hint span{color:var(--cyan);padding:0 4px}.screen-art{position:absolute;right:7%;width:35%;height:72%;display:grid;place-items:center;pointer-events:none}.orbit{position:absolute;width:min(32vw,360px);aspect-ratio:1;border:1px solid #5ef4ef2a;border-radius:50%;transform:rotateX(67deg) rotateZ(-20deg)}.orbit-a:before,.orbit-b:before{content:'';position:absolute;inset:12%;border:1px solid #a883ff30;border-radius:50%}.orbit-b{width:min(26vw,290px);transform:rotateX(67deg) rotateZ(35deg);border-color:#a883ff39}.art-crystal{font-size:clamp(90px,14vw,180px);color:transparent;background:linear-gradient(145deg,#fff 5%,#5ef4ef 28%,#756dff 57%,#ff7ac4 85%);background-clip:text;-webkit-background-clip:text;filter:drop-shadow(0 0 28px #62e9ff9c);animation:float 3s ease-in-out infinite;transform:scaleX(.78) rotate(45deg)}@keyframes float{50%{transform:translateY(-12px) scaleX(.78) rotate(45deg)}}.art-caption{position:absolute;right:0;bottom:0;color:#8290af;font:9px/1.8 'Courier New',monospace;letter-spacing:1px}.art-caption span{color:var(--cyan);margin-left:8px}.art-caption b{color:#dfe6fa;font-weight:400}.compact-panel{width:min(370px,85%);padding:38px}.compact-panel h2{font-size:48px}.compact-panel p{margin-bottom:20px}.text-button{display:block;margin:16px auto 0;border:0;background:none;color:#a7b3d2;font:10px 'Courier New',monospace;letter-spacing:1.5px;cursor:pointer}.text-button:hover{color:var(--cyan)}.result-line{display:flex;justify-content:space-between;padding:12px 0;margin:8px 0 17px;border-top:1px solid #ffffff1a;border-bottom:1px solid #ffffff1a;font:9px 'Courier New',monospace;letter-spacing:1px;color:#9da9c5}.result-line b{color:var(--cyan)}.bottom-note{position:absolute;z-index:3;bottom:14px;left:34px;right:34px;display:flex;justify-content:space-between;color:#8691ac;font:9px 'Courier New',monospace;letter-spacing:1.2px;pointer-events:none}.bottom-note b{font-weight:400;color:#dce7ff;margin-left:8px}.mobile-controls{display:none;position:absolute;z-index:4;inset:auto 0 0;height:35%;justify-content:space-between;align-items:flex-end;padding:0 28px max(24px,env(safe-area-inset-bottom));pointer-events:none;touch-action:none}.stick-zone,.action-controls{pointer-events:auto;touch-action:none}.stick-zone{width:132px;height:132px;position:relative;display:grid;place-items:center}.stick-base{width:112px;height:112px;border-radius:50%;background:#101b3999;border:1px solid #8da7d955;box-shadow:inset 0 0 25px #283a672c;display:grid;place-items:center}.stick-knob{width:48px;height:48px;border-radius:50%;border:1px solid #5ef4ef9c;background:linear-gradient(145deg,#25395fdd,#131b34dd);box-shadow:0 0 20px #5ef4ef28;transform:translate(0,0)}.control-caption{position:absolute;bottom:-2px;left:50%;transform:translateX(-50%);font:8px 'Courier New',monospace;letter-spacing:2px;color:#b8c5e0}.action-controls{display:flex;align-items:flex-end;gap:12px}.touch-button{width:72px;height:72px;border-radius:50%;border:1px solid #9aafff65;background:#121b39cc;color:white;display:flex;flex-direction:column;align-items:center;justify-content:center;box-shadow:0 5px 25px #0006;touch-action:none;user-select:none;-webkit-user-select:none}.touch-button:active,.touch-button.pressed{transform:scale(.94);background:#24345b}.touch-button span{font-size:27px;color:var(--cyan);line-height:1}.touch-button small{margin-top:5px;font:8px 'Courier New',monospace;letter-spacing:1px;color:#c4cce1}.attack-button{width:60px;height:60px;margin-bottom:6px;border-color:#a883ff80}.attack-button .attack-icon{color:#b69cff}.rotate-notice{display:none}.rotate-card{display:grid;gap:12px;text-align:center;color:#fff}.rotate-card>span{font-size:36px;color:var(--cyan)}.rotate-card b{font:12px 'Courier New',monospace;letter-spacing:2px}.rotate-card small{font:9px 'Courier New',monospace;color:#9da9c5;letter-spacing:1px}
@media(max-width:720px){.topbar{height:56px;padding:0 16px}.brand-name{font-size:10px;letter-spacing:1.5px}.brand-mark{width:26px;height:26px;font-size:16px}.mission{font-size:8px;letter-spacing:1px}.icon-button{width:36px;height:36px}.hud{top:68px;left:12px;gap:5px}.hud-card{min-width:88px;padding:8px 9px}.crystal-card{min-width:108px}.health-card{min-width:89px}.progress-card{min-width:90px}.hud-label{font-size:7px;letter-spacing:.8px}.crystal-count{margin:3px 0 6px}.crystal-count strong{font-size:21px}.hearts{font-size:16px;gap:3px}.progress-line{margin-top:10px;gap:4px}.progress-line .meter{width:40px}.progress-line>span{font-size:9px;min-width:24px}.screen-panel{width:min(420px,90%);padding:28px;margin-right:0}.screen-art{right:-10%;width:52%;height:45%;opacity:.25}.intro-panel{background:linear-gradient(120deg,rgba(12,18,44,.97),rgba(7,11,29,.88))}.screen h1{font-size:clamp(42px,11vw,62px)}.mission-stats{margin:18px 0}.bottom-note{left:16px;right:16px;bottom:8px;font-size:8px}.mobile-controls{display:flex}.game-shell{height:100dvh;width:100vw}.hud{transform:scale(.93);transform-origin:top left}}
@media(max-width:700px) and (orientation:portrait){.rotate-notice{display:flex!important;z-index:10;background:#080b1b}.rotate-card{padding:28px}.mobile-controls{height:32%}.hud{top:62px}}
@media(max-height:500px) and (orientation:landscape){.topbar{height:46px}.hud{top:52px}.hud-card{padding:6px 9px}.screen-panel{padding:20px 28px}.screen h1{font-size:42px;margin:12px 0}.intro-copy{font-size:11px;margin:8px 0}.mission-stats{margin:12px 0}.primary-button{height:40px}.key-hint{margin-top:9px}.mobile-controls{height:45%;padding-bottom:10px}.stick-zone{transform:scale(.78);transform-origin:bottom left}.touch-button{width:62px;height:62px}.attack-button{width:52px;height:52px}.bottom-note{bottom:5px}}

