function drawBackground(t){
  const sky=ctx.createLinearGradient(0,0,0,height);sky.addColorStop(0,'#101937');sky.addColorStop(.52,'#17234a');sky.addColorStop(1,'#111831');ctx.fillStyle=sky;ctx.fillRect(0,0,width,height);
